function textStats(s){
  s=String(s||'');
  var chars=s.length;
  var noSpace=s.replace(/\s/g,'').length;
  var lines=s.split(/\n/).length;
  var words=s.trim()? s.trim().split(/\s+/).length : 0;
  var cjk=(s.match(/[一-龥]/g)||[]).length;
  var readingMin=Math.max(1, Math.round((words + cjk/2)/200));
  return {chars:chars, noSpace:noSpace, words:words, lines:lines, cjk:cjk, readingMin:readingMin};
}

var EXPORTS={textStats:textStats};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TextStatsForgePure = EXPORTS; }
